`ifndef XIL_XECLIB
  always @ (trig_attr) begin
    #1;
    if ((attr_test == 1'b1) ||
        ((DISPLAY_CONTROLLER_MODE_REG != "FUNCTIONAL") &&
         (DISPLAY_CONTROLLER_MODE_REG != "BYPASS"))) begin
      $display("Error: [Unisim %s-101] DISPLAY_CONTROLLER_MODE attribute is set to %s.  Legal values for this attribute are FUNCTIONAL or BYPASS. Instance: %m", MODULE_NAME, DISPLAY_CONTROLLER_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DISPLAY_PORT_ENABLE_REG != "ON") &&
         (DISPLAY_PORT_ENABLE_REG != "OFF"))) begin
      $display("Error: [Unisim %s-102] DISPLAY_PORT_ENABLE attribute is set to %s.  Legal values for this attribute are ON or OFF. Instance: %m", MODULE_NAME, DISPLAY_PORT_ENABLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((DISPLAY_PORT_LANES_REG != 2) &&
         (DISPLAY_PORT_LANES_REG != 1) &&
         (DISPLAY_PORT_LANES_REG != 4))) begin
      $display("Error: [Unisim %s-103] DISPLAY_PORT_LANES attribute is set to %d.  Legal values for this attribute are 2, 1 or 4. Instance: %m", MODULE_NAME, DISPLAY_PORT_LANES_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((ETHERNET_ENABLE_REG != "OFF") &&
         (ETHERNET_ENABLE_REG != "ON"))) begin
      $display("Error: [Unisim %s-104] ETHERNET_ENABLE attribute is set to %s.  Legal values for this attribute are OFF or ON. Instance: %m", MODULE_NAME, ETHERNET_ENABLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        (GPU_CORE0_ACTIVITY_FACTOR_REG < 0.0 || GPU_CORE0_ACTIVITY_FACTOR_REG > 1.0)) begin
      $display("Error: [Unisim %s-105] GPU_CORE0_ACTIVITY_FACTOR attribute is set to %f.  Legal values for this attribute are 0.0 to 1.0. Instance: %m", MODULE_NAME, GPU_CORE0_ACTIVITY_FACTOR_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((GPU_CORE0_CLOCK_ENABLE_REG != "ON") &&
         (GPU_CORE0_CLOCK_ENABLE_REG != "OFF"))) begin
      $display("Error: [Unisim %s-106] GPU_CORE0_CLOCK_ENABLE attribute is set to %s.  Legal values for this attribute are ON or OFF. Instance: %m", MODULE_NAME, GPU_CORE0_CLOCK_ENABLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((GPU_CORE0_POWER_ENABLE_REG != "ON") &&
         (GPU_CORE0_POWER_ENABLE_REG != "OFF"))) begin
      $display("Error: [Unisim %s-107] GPU_CORE0_POWER_ENABLE attribute is set to %s.  Legal values for this attribute are ON or OFF. Instance: %m", MODULE_NAME, GPU_CORE0_POWER_ENABLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        (GPU_CORE1_ACTIVITY_FACTOR_REG < 0.0 || GPU_CORE1_ACTIVITY_FACTOR_REG > 1.0)) begin
      $display("Error: [Unisim %s-108] GPU_CORE1_ACTIVITY_FACTOR attribute is set to %f.  Legal values for this attribute are 0.0 to 1.0. Instance: %m", MODULE_NAME, GPU_CORE1_ACTIVITY_FACTOR_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((GPU_CORE1_CLOCK_ENABLE_REG != "ON") &&
         (GPU_CORE1_CLOCK_ENABLE_REG != "OFF"))) begin
      $display("Error: [Unisim %s-109] GPU_CORE1_CLOCK_ENABLE attribute is set to %s.  Legal values for this attribute are ON or OFF. Instance: %m", MODULE_NAME, GPU_CORE1_CLOCK_ENABLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((GPU_CORE1_POWER_ENABLE_REG != "ON") &&
         (GPU_CORE1_POWER_ENABLE_REG != "OFF"))) begin
      $display("Error: [Unisim %s-110] GPU_CORE1_POWER_ENABLE attribute is set to %s.  Legal values for this attribute are ON or OFF. Instance: %m", MODULE_NAME, GPU_CORE1_POWER_ENABLE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        (GPU_CORE2_ACTIVITY_FACTOR_REG < 0.0 || GPU_CORE2_ACTIVITY_FACTOR_REG > 1.0)) begin
      $display("Error: [Unisim %s-111] GPU_CORE2_ACTIVITY_FACTOR attribute is set to %f.  Legal values for this attribute are 0.0 to 1.0. Instance: %m", MODULE_NAME, GPU_CORE2_ACTIVITY_FACTOR_REG);
      attr_err = 1'b1;
    end
    
